            if neighbors[0] != 0 and all(v == neighbors[0] for v in neighbors):
                centers.setdefault(grid[r][c], set()).add((r, c))

    # A color may form several independent rectangles, so test all coordinate
    # pairs rather than requiring exactly four cells of that color globally.
    for color, points in centers.items():
        if color == 0:
            continue
        rows = sorted({r for r, _ in points})
