def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = {}

    # Treat each 4-connected same-color object as a motif instance.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            shape = frozenset((y-r0, x-c0) for y, x in cells)
            components.setdefault((color, shape), []).append((r0, c0))

    # Four identical components at the corners of one rectangle are linked
    # along corresponding rows and columns, painting only blank cells.
    for (color, shape), origins in components.items():
        if len(origins) != 4:
            continue
        rows = sorted({r for r, _ in origins})
        cols = sorted({c for _, c in origins})
        if len(rows) != 2 or len(cols) != 2 or set(origins) != {
