                    if grid[r + dy][c] == 0:
                        out[r + dy][c] = color
            for c in cols:
                for r in range(rows[0] + dy + 1, rows[1] + dy):
                    if grid[r][c + dx] == 0:
                        out[r][c + dx] = color
    return out
